/**
 * Listing Translations API
 * ========================
 * GET /api/listings/{id}/translations?lang=en
 *
 * Returns pre-computed translations for a listing in the requested language.
 * Generated by the V5 pipeline (v5_translations stage) so language switching
 * in the UI is instant — no on-demand translation API calls needed.
 *
 * Response format:
 *   { success, hasTranslations, language, translations: { sourceText: translatedText } }
 *
 * The `translations` map uses the original Spanish text as key and the
 * translated text as value, so the frontend can directly seed its cache.
 */
import { NextRequest, NextResponse } from "next/server";

export const dynamic = "force-dynamic";

const SB_URL = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const SB_KEY =
  process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_KEY || "";

const headers = {
  apikey: SB_KEY,
  Authorization: `Bearer ${SB_KEY}`,
  "Content-Type": "application/json",
};

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  const lang = request.nextUrl.searchParams.get("lang") || "en";

  try {
    const url = `${SB_URL}/rest/v1/unified_estimates?listing_id=eq.${id}&package_type=eq.v5_translations&select=estimate_data`;
    const r = await fetch(url, { headers, cache: "no-store" });
    if (!r.ok) {
      return NextResponse.json({ success: true, hasTranslations: false });
    }

    const rows = await r.json();
    const data = rows?.[0]?.estimate_data;

    if (!data?.languages?.[lang] || !data?.source_texts) {
      return NextResponse.json({ success: true, hasTranslations: false });
    }

    const langData = data.languages[lang] as Record<string, string>;
    if (langData._error) {
      return NextResponse.json({ success: true, hasTranslations: false });
    }

    const sourceTexts = data.source_texts as Record<string, string>;

    // Build sourceText → translatedText map for direct cache seeding
    const translations: Record<string, string> = {};
    for (const [key, translatedText] of Object.entries(langData)) {
      const sourceText = sourceTexts[key];
      if (sourceText && translatedText) {
        translations[sourceText] = translatedText;
      }
    }

    return NextResponse.json({
      success: true,
      hasTranslations: true,
      language: lang,
      translations,
      count: Object.keys(translations).length,
    });
  } catch (error) {
    console.error(`[listings/${id}/translations] error:`, error);
    return NextResponse.json({ success: true, hasTranslations: false });
  }
}
